use std::process::Command;

fn main() {
    // Execute the strykelang binary (installed via post_install) with --version flag
    let output = Command::new("stryke")
        .arg("--version")
        .output()
        .expect("failed to execute strykelang binary");

    if !output.status.success() {
        panic!("stryke returned a non‑zero exit code");
    }

    let version_raw = String::from_utf8_lossy(&output.stdout);
    let version = version_raw.trim();
    // Emit JSON with the version field
    println!("{{\"version\":\"{}\"}}", version);
}
